/* <title> | name="description" | property="og: */
'use client'

import { useEffect, useState, useRef } from 'react'
import { useServices } from '@/lib/services'
import { useParams, useRouter } from 'next/navigation'
import { Avatar } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { Database } from '@/types/database.types'
import { ArrowLeft, Send, Loader2 } from 'lucide-react'

type Message = Database['public']['Tables']['messages']['Row']
type Profile = Database['public']['Tables']['profiles']['Row']
type Connection = Database['public']['Tables']['connections']['Row']

export default function ChatPage() {
    const { supabase, messagesService } = useServices()
    const router = useRouter()
    const params = useParams()
    const connectionId = params.id as string

    const [messages, setMessages] = useState<Message[]>([])
    const [newMessage, setNewMessage] = useState('')
    const [loading, setLoading] = useState(true)
    const [sending, setSending] = useState(false)
    const [currentUserId, setCurrentUserId] = useState<string | null>(null)
    const [partner, setPartner] = useState<Profile | null>(null)
    const messagesEndRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
        async function init() {
            const { data: { user } } = await supabase.auth.getUser()
            if (!user) return
            setCurrentUserId(user.id)

            // Get connection info
            const { data: connection } = await supabase
                .from('connections')
                .select('*')
                .eq('id', connectionId)
                .single() as { data: Connection | null }

            if (connection) {
                const partnerId = connection.requester_id === user.id
                    ? connection.receiver_id
                    : connection.requester_id

                const { data: partnerData } = await supabase
                    .from('profiles')
                    .select('*')
                    .eq('id', partnerId)
                    .single()

                setPartner(partnerData)
            }

            // Fetch messages using Service
            const { data: messagesData } = await messagesService.getHistory(connectionId)

            if (messagesData) {
                setMessages(messagesData as unknown as Message[])
            }
            setLoading(false)
        }

        init()
    }, [supabase, connectionId])

    // Realtime subscription via Service
    useEffect(() => {
        if (!currentUserId || !connectionId) return

        const channel = messagesService.subscribeToChat(
            connectionId,
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (payload: any) => {
                const newMsg = payload.new as Message
                // Prevent duplicate from optimistic update
                if (newMsg.sender_id === currentUserId) return

                setMessages((prev) => {
                    if (prev.some(m => m.id === newMsg.id)) return prev
                    return [...prev, newMsg]
                })
            }
        )

        return () => {
            messagesService.unsubscribe(channel)
        }
    }, [messagesService, connectionId, currentUserId])

    // Scroll to bottom on new messages
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
    }, [messages])

    const handleSend = async (e: React.FormEvent) => {
        e.preventDefault()
        if (!newMessage.trim() || !currentUserId) return

        const messageContent = newMessage.trim()
        setNewMessage('')
        setSending(true)

        // Optimistic update
        const optimisticMsg: Message = {
            id: crypto.randomUUID(),
            connection_id: connectionId,
            sender_id: currentUserId,
            content: messageContent,
            created_at: new Date().toISOString()
        }
        setMessages((prev) => [...prev, optimisticMsg])

        const { error } = await messagesService.sendMessage(
            connectionId,
            currentUserId,
            messageContent
        )

        if (error) {
            console.error('Error sending message:', error)
            // Rollback
            setMessages((prev) => prev.filter((m) => m.id !== optimisticMsg.id))
            setNewMessage(messageContent) // Restore text
        }

        setSending(false)
    }

    if (loading) {
        return (
            <div className="flex items-center justify-center h-screen">
                <Loader2 className="w-8 h-8 animate-spin text-emerald-500" />
            </div>
        )
    }

    if (!partner) {
        return (
            <div className="flex flex-col items-center justify-center h-screen p-4 text-center">
                <div className="bg-red-100 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-4 rounded-lg">
                    <h3 className="font-bold mb-2">Erro ao carregar chat</h3>
                    <p className="text-sm">Não foi possível encontrar a conexão ou o usuário.</p>
                    <p className="text-xs mt-1">Verifique se você aceitou a conexão.</p>
                </div>
                <Button onClick={() => router.push('/network')} className="mt-4" variant="secondary">
                    Voltar para Rede
                </Button>
            </div>
        )
    }

    return (
        <div className="flex flex-col h-screen bg-white dark:bg-zinc-950">
            {/* Header */}
            <header className="flex items-center gap-3 p-4 border-b border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-950 sticky top-0 z-10">
                <button onClick={() => router.back()} className="p-1">
                    <ArrowLeft className="w-6 h-6 text-zinc-600 dark:text-zinc-400" />
                </button>
                <Avatar
                    size="md"
                    src={partner?.photos?.[0]}
                    fallback={partner?.full_name || 'U'}
                />
                <div className="flex-1">
                    <h1 className="font-semibold text-zinc-900 dark:text-white">
                        {partner?.full_name}
                    </h1>
                    <p className="text-xs text-zinc-500">{partner?.university}</p>
                </div>
            </header>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 space-y-3 no-scrollbar">
                {messages.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full text-center">
                        <p className="text-zinc-500 text-sm">
                            Inicie a conversa com {partner?.full_name?.split(' ')[0]}!
                        </p>
                    </div>
                ) : (
                    messages.map((msg) => {
                        const isMine = msg.sender_id === currentUserId
                        return (
                            <div
                                key={msg.id}
                                className={`flex ${isMine ? 'justify-end' : 'justify-start'}`}
                            >
                                <div
                                    className={`max-w-[75%] px-4 py-2 rounded-2xl ${isMine
                                        ? 'bg-emerald-500 text-white rounded-br-md'
                                        : 'bg-zinc-100 dark:bg-zinc-800 text-zinc-900 dark:text-white rounded-bl-md'
                                        }`}
                                >
                                    <p className="text-sm">{msg.content}</p>
                                    <p
                                        className={`text-[10px] mt-1 ${isMine ? 'text-emerald-100' : 'text-zinc-400'
                                            }`}
                                    >
                                        {new Date(msg.created_at).toLocaleTimeString('pt-BR', {
                                            hour: '2-digit',
                                            minute: '2-digit',
                                        })}
                                    </p>
                                </div>
                            </div>
                        )
                    })
                )}
                <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <form
                onSubmit={handleSend}
                className="flex items-center gap-2 p-4 border-t border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-950 safe-area-bottom"
            >
                <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    placeholder="Digite sua mensagem..."
                    className="flex-1 h-11 px-4 rounded-full border border-zinc-200 dark:border-zinc-700 bg-zinc-50 dark:bg-zinc-900 text-zinc-900 dark:text-white placeholder:text-zinc-400 focus:outline-none focus:ring-2 focus:ring-emerald-500"
                />
                <Button
                    type="submit"
                    size="md"
                    className="rounded-full w-11 h-11 p-0"
                    disabled={!newMessage.trim() || sending}
                    aria-label={sending ? 'Enviando mensagem...' : 'Enviar mensagem'}
                >
                    {sending ? (
                        <Loader2 className="w-5 h-5 animate-spin" />
                    ) : (
                        <Send className="w-5 h-5" />
                    )}
                </Button>
            </form>
        </div>
    )
}

import { SupabaseClient } from '@supabase/supabase-js'
import { Database } from '@/types/database.types'

export class ConnectionsService {
    constructor(private supabase: SupabaseClient<Database>) { }

    async getAcceptedConnections(userId: string) {
        return this.supabase
            .from('connections')
            .select('*')
            .eq('status', 'accepted')
            .or(`requester_id.eq.${userId},receiver_id.eq.${userId}`)
    }

    async getPendingReceivedRequests(userId: string) {
        return this.supabase
            .from('connections')
            .select('*')
            .eq('receiver_id', userId)
            .eq('status', 'pending')
    }

    async getPendingSentRequests(userId: string) {
        return this.supabase
            .from('connections')
            .select('*')
            .eq('requester_id', userId)
            .eq('status', 'pending')
    }

    async acceptRequest(connectionId: string) {
        return this.supabase
            .from('connections')
            // @ts-expect-error - Supabase types require real database
            .update({ status: 'accepted' })
            .eq('id', connectionId)
    }

    async rejectRequest(connectionId: string) {
        return this.supabase
            .from('connections')
            // @ts-expect-error - Supabase types require real database
            .update({ status: 'rejected' })
            .eq('id', connectionId)
    }

    async sendRequest(requesterId: string, receiverId: string) {
        return this.supabase
            .from('connections')
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            .insert({
                requester_id: requesterId,
                receiver_id: receiverId,
                status: 'pending',
            } as any)
    }

    subscribeToConnectionUpdates(
        userId: string,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        onUpdate: (payload: any) => void,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        onInsert: (payload: any) => void
    ) {
        return this.supabase
            .channel('connections-realtime')
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'connections',
                    filter: `requester_id=eq.${userId}`, // Also useful to check receiver, we can broaden the filter inside.
                },
                onUpdate
            )
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'connections',
                    filter: `receiver_id=eq.${userId}`,
                },
                onUpdate
            )
            .on(
                'postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'connections',
                    filter: `receiver_id=eq.${userId}`,
                },
                onInsert
            )
            .subscribe()
    }

    unsubscribe(channel: ReturnType<SupabaseClient['channel']>) {
        this.supabase.removeChannel(channel)
    }

    async checkIfConnected(userId: string, targetId: string) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        return this.supabase.rpc('are_connected', { user1_id: userId, user2_id: targetId })
    }
}

import { SupabaseClient } from '@supabase/supabase-js'
import { Database } from '@/types/database.types'

export class MessagesService {
    constructor(private supabase: SupabaseClient<Database>) { }

    async getHistory(connectionId: string) {
        return this.supabase
            .from('messages')
            .select(`
                id,
                connection_id,
                sender_id,
                content,
                created_at,
                profiles:sender_id (
                    full_name,
                    photos
                )
            `)
            .eq('connection_id', connectionId)
            .order('created_at', { ascending: true })
    }

    async getLatestMessage(connectionId: string) {
        return this.supabase
            .from('messages')
            .select('content, created_at, sender_id')
            .eq('connection_id', connectionId)
            .order('created_at', { ascending: false })
            .limit(1)
    }

    async sendMessage(connectionId: string, senderId: string, content: string) {
        return this.supabase
            .from('messages')
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            .insert({
                connection_id: connectionId,
                sender_id: senderId,
                content,
            } as any)
    }

    subscribeToChat(
        connectionId: string,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        onNewMessage: (payload: any) => void
    ) {
        return this.supabase
            .channel(`chat-${connectionId}`)
            .on(
                'postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'messages',
                    filter: `connection_id=eq.${connectionId}`,
                },
                onNewMessage
            )
            .subscribe()
    }

    unsubscribe(channel: ReturnType<SupabaseClient['channel']>) {
        this.supabase.removeChannel(channel)
    }
}
